import sys, itertools
from collections import defaultdict

def build(a,b,c,d,e):
    tuples=[(a,b,1.0),(b,c,2.0),(c,d,3.0),(d,e,4.0),(a,e,5.0)]
    nodes=[]  # insertion order
    adj={}    # node -> dict of nbr->weight, insertion ordered
    def addn(n):
        if n not in adj:
            adj[n]={}; nodes.append(n)
    for (u,v,w) in tuples:
        addn(u); addn(v)
        adj[u][v]=w; adj[v][u]=w
    return nodes, adj

def edges(nodes,adj):
    seen=set(); out=[]
    for u in nodes:
        for v,w in adj[u].items():
            k=frozenset((u,v))
            if k in seen: continue
            seen.add(k); out.append((u,v,w))
    return out

def degree(n,adj):
    d=0
    for v in adj[n]:
        d += 2 if v==n else 1
    return d

def is_connected(nodes,adj):
    st=[nodes[0]]; seen={nodes[0]}
    while st:
        u=st.pop()
        for v in adj[u]:
            if v not in seen: seen.add(v); st.append(v)
    return len(seen)==len(nodes)

def mst_edges(nodes,adj):
    es=sorted(edges(nodes,adj), key=lambda t:t[2])
    par={n:n for n in nodes}
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    out=[]
    for u,v,w in es:
        ru,rv=find(u),find(v)
        if ru!=rv: par[ru]=rv; out.append((u,v,w))
    return out

def local_nc(nodes,adj,s,t):
    # max node-disjoint paths s->t via maxflow on split graph
    # nodes: xIN=(x,0) xOUT=(x,1)
    cap=defaultdict(int)
    graph=defaultdict(set)
    INF=10**6
    def ae(x,y,c):
        cap[(x,y)]+=c
        graph[x].add(y); graph[y].add(x)
    for n in nodes:
        c = INF if n in (s,t) else 1
        ae((n,0),(n,1),c)
    for u,v,w in edges(nodes,adj):
        if u==v: continue
        ae((u,1),(v,0),INF)
        ae((v,1),(u,0),INF)
    src=(s,1); snk=(t,0)
    flow=0
    while True:
        # BFS augment
        prev={src:None}; q=[src]
        while q:
            nq=[]
            for x in q:
                for y in graph[x]:
                    if y not in prev and cap[(x,y)]>0:
                        prev[y]=x; nq.append(y)
            q=nq
            if snk in prev: break
        if snk not in prev: break
        # find bottleneck
        path=[]; cur=snk
        while prev[cur] is not None:
            path.append((prev[cur],cur)); cur=prev[cur]
        bn=min(cap[ed] for ed in path)
        for (x,y) in path:
            cap[(x,y)]-=bn; cap[(y,x)]+=bn
        flow+=bn
    return flow

def node_connectivity(nodes,adj,tiebreak='first'):
    if not is_connected(nodes,adj): return 0
    degs=[(n,degree(n,adj)) for n in nodes]
    m=min(d for _,d in degs)
    cands=[n for n,d in degs if d==m]
    v = cands[0] if tiebreak=='first' else cands[-1]
    K=m
    nbrs=list(adj[v])
    for w in set(nodes)-set(nbrs)-{v}:
        K=min(K, local_nc(nodes,adj,v,w))
    for x,y in itertools.combinations(nbrs,2):
        if y in adj[x]: continue
        K=min(K, local_nc(nodes,adj,x,y))
    return K

def true_vc(nodes,adj):
    # vertex connectivity of simple graph ignoring self loops
    sadj={n:set(x for x in adj[n] if x!=n) for n in nodes}
    n=len(nodes)
    if n==1: return 0
    # connected?
    if not is_connected(nodes,adj): return 0
    if all(len(sadj[x])==n-1 for x in nodes): return n-1
    best=10**9
    for x,y in itertools.combinations(nodes,2):
        if y in sadj[x]: continue
        best=min(best, local_nc(nodes,adj,x,y))
    return best

def run(a,b,c,d,e):
    nodes,adj=build(a,b,c,d,e)
    ne=len(edges(nodes,adj))
    w=adj[a][b]
    m=mst_edges(nodes,adj)
    he=any(frozenset((u,v))==frozenset((a,b)) for u,v,_ in m) and a!=b
    nc=node_connectivity(nodes,adj)
    nc2=node_connectivity(nodes,adj,'last')
    tv=true_vc(nodes,adj)
    return ne,w,len(m),he,nc,nc2,tv,len(nodes)

if __name__=='__main__':
    for line in sys.stdin:
        p=line.split()
        if len(p)!=5: continue
        a,b,c,d,e=map(int,p)
        print("|".join(p), *run(a,b,c,d,e), sep="\t")
